package com.muthumol.player.dummy;
import android.content.Context;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** Poster-only TV card. Episode identity is a label, never a scene screenshot. */
final class MovieCardView extends LinearLayout {
 Movie movie;final PosterArtView art;final TextView name,episode;final ProgressBar progress;final FrameLayout cover;
 MovieCardView(Context c,Movie m,boolean compact){super(c);setOrientation(VERTICAL);setId(View.generateViewId());setFocusable(true);setClickable(true);setDescendantFocusability(FOCUS_BLOCK_DESCENDANTS);setPadding(Ui.dp(c,4),Ui.dp(c,5),Ui.dp(c,4),Ui.dp(c,3));
  cover=new FrameLayout(c);art=new PosterArtView(c,240,360);cover.addView(art,new FrameLayout.LayoutParams(-1,-1));episode=Ui.text(c,"",compact?8:9,Color.WHITE);episode.setTypeface(Typeface.DEFAULT_BOLD);episode.setPadding(Ui.dp(c,4),Ui.dp(c,2),Ui.dp(c,4),Ui.dp(c,2));GradientDrawable pill=new GradientDrawable();pill.setColor(TmStyle.RAISED);pill.setCornerRadius(Ui.dp(c,5));episode.setBackground(pill);FrameLayout.LayoutParams ep=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT);ep.setMargins(3,Ui.dp(c,5),Ui.dp(c,5),0);cover.addView(episode,ep);addView(cover,new LayoutParams(-1,Ui.dp(c,c instanceof MainActivity&&((MainActivity)c).phoneLayout()?192:compact?90:154)));
  name=Ui.text(c,"",compact?10:12,Color.WHITE);name.setPadding(0,Ui.dp(c,4),0,0);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);addView(name,new LayoutParams(-1,Ui.dp(c,compact?18:21)));progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(TmStyle.ACCENT));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(TmStyle.OUTLINE));addView(progress,new LayoutParams(-1,Ui.dp(c,2)));bind(m);highlight(false);
 }
 void bind(Movie m){movie=m;MediaTitle info=MediaTitle.parse(m.uiTitle(getContext()));name.setText(info.name);episode.setText(String.format(java.util.Locale.US,"S%02d · E%02d",info.season,info.episode));episode.setVisibility(info.episodic()?VISIBLE:GONE);setContentDescription(info.display()+" • OK to play");art.show(m,Ui.color(getContext()));long duration=m.duration*1000L;if(duration<=0)duration=getContext().getSharedPreferences("player",0).getLong("duration:"+m.cacheIdentity(),0);long pos=m.savedPosition(getContext());progress.setProgress(CinemaInfo.progress(pos,duration));progress.setVisibility(pos>0?VISIBLE:INVISIBLE);}
 void highlight(boolean focused){GradientDrawable outline=new GradientDrawable();outline.setColor(Color.TRANSPARENT);outline.setCornerRadius(Ui.dp(getContext(),12));if(focused)outline.setStroke(Ui.dp(getContext(),3),TmStyle.ACCENT);cover.setForeground(outline);if(!focused){outline.setStroke(Ui.dp(getContext(),1),0x40e4f3ff);}name.setTextColor(focused?Color.WHITE:TmStyle.MUTED);name.setTypeface(focused?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);TvMotion.focus(this,focused,1.075f);}
}

